    class BlurFilterGLRender {
        render(rt, ctx, width, height, filter) {
            var shaderValueH = Value2D.create(ShaderDefines2D.TEXTURE2D, 0);
            var shaderValueV = Value2D.create(ShaderDefines2D.TEXTURE2D, 0);
            var shaderValueDS = Value2D.create(ShaderDefines2D.TEXTURE2D, 0);
            let scaleFactor = 1 / (1 << Math.floor(filter.strength));
            let tw = Math.floor(width * scaleFactor);
            let th = Math.floor(height * scaleFactor);
            let rtH = WebGLRTMgr.getRT(tw, th);
            let rtV = WebGLRTMgr.getRT(tw, th);
            ctx.pushRT();
            ctx.useRT(rtV);
            ctx.drawTarget(rt, 0, 0, tw, th, Matrix.EMPTY.identity(), shaderValueDS, RenderTexture2D.flipyuv);
            for (let i = 0; i < filter.blurIterations; i++) {
                this.setShaderInfo(shaderValueH, filter, tw, th, BlurFilterGLRender.dirH);
                ctx.useRT(rtH);
                ctx.drawTarget(rtV, 0, 0, tw, th, Matrix.EMPTY.identity(), shaderValueH);
                ctx.useRT(rtV);
                this.setShaderInfo(shaderValueV, filter, tw, th, BlurFilterGLRender.dirV);
                ctx.drawTarget(rtH, 0, 0, tw, th, Matrix.EMPTY.identity(), shaderValueV);
            }
            ctx.popRT();
            ctx.drawTarget(rtV, 0, 0, width, height, Matrix.EMPTY.identity(), Value2D.create(ShaderDefines2D.TEXTURE2D, 0));
            let submit = SubmitCMD.create([rtH, rtV], function (s1, s2) {
                WebGLRTMgr.releaseRT(s1);
                WebGLRTMgr.releaseRT(s2);
            }, this);
            ctx.addRenderObject(submit);
        }
        setShaderInfo(shader, filter, w, h, dir) {
            shader.defines.add(Filter.BLUR);
            var sv = shader;
            BlurFilterGLRender.u_MainTex_TexelSize[0] = 1.0 / w;
            BlurFilterGLRender.u_MainTex_TexelSize[1] = 1.0 / h;
            sv.u_MainTex_TexelSize = BlurFilterGLRender.u_MainTex_TexelSize;
            sv.u_DownSampleValue = filter.spreadSize;
            sv.u_Direction = dir;
        }
        setShaderInfoDS(shader) {
            shader.defines.add(Filter.DOWN_SAMPLE);
        }
    }
    BlurFilterGLRender.u_MainTex_TexelSize = new Array(2);
    BlurFilterGLRender.dirH = [1, 0];
    BlurFilterGLRender.dirV = [0, 1];

    class BlurFilter extends Filter {
        constructor(strength = 6, spreadSize = 1, blurIterations = 1) {
            super();
            this.strength_sig2_2sig2_gauss1 = [];
            this.strength = strength;
            this.spreadSize = spreadSize;
            this.blurIterations = blurIterations;
            this._glRender = new BlurFilterGLRender();
        }
        get type() {
            return Filter.BLUR;
        }
        set strength(value) {
            this._strength = Math.min(6, Math.max(value, 0.0));
        }
        get strength() {
            return this._strength;
        }
        get spreadSize() {
            return this._spreadSize;
        }
        set spreadSize(value) {
            this._spreadSize = Math.min(10, Math.max(value, 1.0));
        }
        get blurIterations() {
            return this._blurIterations;
        }
        set blurIterations(value) {
            this._blurIterations = Math.min(Math.max(value, 0.0), 6.0);
        }
        getStrenth_sig2_2sig2_native() {
            if (!this.strength_sig2_native) {
                this.strength_sig2_native = new Float32Array(4);
            }
            var sigma = this.strength / 3.0;
            var sigma2 = sigma * sigma;
            this.strength_sig2_native[0] = this.strength;
            this.strength_sig2_native[1] = sigma2;
            this.strength_sig2_native[2] = 2.0 * sigma2;
            this.strength_sig2_native[3] = 1.0 / (2.0 * Math.PI * sigma2);
            return this.strength_sig2_native;
        }
    }

