    class ButtonEffect {
        constructor() {
            this._curState = 0;
            this.effectScale = 1.2;
            this.tweenTime = 100;
            this._initScaleX = 0;
            this._initScaleY = 0;
        }
        set target(tar) {
            if (this._tar === tar)
                return;
            this.clear();
            if (tar == null)
                return;
            this._tar = tar;
            tar.on(Event.MOUSE_DOWN, this, this.toChangedState);
            tar.on(Event.MOUSE_UP, this, this.toInitState);
            tar.on(Event.MOUSE_OUT, this, this.toInitState);
        }
        clear() {
            if (this._tar) {
                this._tar.off(Event.MOUSE_DOWN, this, this.toChangedState);
                this._tar.off(Event.MOUSE_UP, this, this.toInitState);
                this._tar.off(Event.MOUSE_OUT, this, this.toInitState);
            }
            this._tar = null;
            this._curState = 0;
            this.effectScale = 1.2;
            this.tweenTime = 100;
            this._initScaleX = 0;
            this._initScaleY = 0;
        }
        toChangedState() {
            if (this._tar && this._initScaleX == 0 && this._initScaleY == 0) {
                this._initScaleX = this._tar.scaleX;
                this._initScaleY = this._tar.scaleY;
            }
            this._curState = 1;
            if (this._curTween)
                Tween.clear(this._curTween);
            this._curTween = Tween.to(this._tar, { scaleX: this.effectScale * this._initScaleX, scaleY: this.effectScale * this._initScaleY }, this.tweenTime, Ease[this.effectEase], Handler.create(this, this.tweenComplete));
        }
        toInitState() {
            if (this._curState == 2)
                return;
            if (this._curState == 1) {
                if (this._curTween)
                    Tween.clear(this._curTween);
                this._curState = 2;
                this._curTween = Tween.to(this._tar, { scaleX: this._initScaleX, scaleY: this._initScaleY }, this.tweenTime, Ease[this.backEase], Handler.create(this, this.tweenComplete));
            }
        }
        tweenComplete() {
            if (this._curState == 2)
                this._curState = 0;
            this._curTween = null;
        }
    }

