	class HBox extends LayoutBox {
	    constructor() {
	        super(...arguments);
	        this.dir = "L2R";
	    }
	    sortItem(items) {
	        if (items)
	            items.sort(function (a, b) { return a.x - b.x; });
	    }
	    set height(value) {
	        if (this._height != value) {
	            super.height = value;
	            this.callLater(this.changeItems);
	        }
	    }
	    get height() {
	        return super.height;
	    }
	    changeItems() {
	        this._itemChanged = false;
	        var items = [];
	        var maxHeight = 0;
	        for (var i = 0, n = this.numChildren; i < n; i++) {
	            var item = this.getChildAt(i);
	            if (item) {
	                items.push(item);
	                maxHeight = this._height ? this._height : Math.max(maxHeight, item.height * item.scaleY);
	            }
	        }
	        if (this._sortItemFun) {
	            this._sortItemFun(items);
	        }
	        else {
	            this.sortItem(items);
	        }
	        if (this.dir == "L2R") {
	            this._updatePosL2R(items, maxHeight);
	        }
	        else {
	            this._updatePosR2L(items, maxHeight);
	        }
	        this._sizeChanged();
	    }
	    _updatePosL2R(items, maxHeight) {
	        var left = 0;
	        for (let i = 0, n = items.length; i < n; i++) {
	            let item = items[i];
	            item.x = left;
	            left += item.width * item.scaleX + this._space;
	            if (this._align == HBox.TOP) {
	                item.y = 0;
	            }
	            else if (this._align == HBox.MIDDLE) {
	                item.y = (maxHeight - item.height * item.scaleY) * 0.5;
	            }
	            else if (this._align == HBox.BOTTOM) {
	                item.y = maxHeight - item.height * item.scaleY;
	            }
	        }
	    }
	    _updatePosR2L(items, maxHeight) {
	        var left = this.width;
	        for (let i = 0, n = items.length; i < n; i++) {
	            let item = items[i];
	            item.x = left - item.width * item.scaleX;
	            left -= item.width * item.scaleX + this._space;
	            if (this._align == HBox.TOP) {
	                item.y = 0;
	            }
	            else if (this._align == HBox.MIDDLE) {
	                item.y = (maxHeight - item.height * item.scaleY) * 0.5;
	            }
	            else if (this._align == HBox.BOTTOM) {
	                item.y = maxHeight - item.height * item.scaleY;
	            }
	        }
	    }
	}
